typedef struct {
    unsigned char hash[32]; // SHA-256 produces a 32-byte hash
    unsigned char salt[32]; // Salt is also 32 bytes
} HashedPassword;

HashedPassword* hash_passwords(int count, char** usernames, char** passwords) {
    HashedPassword* hashed_passwords = malloc(count * sizeof(HashedPassword));
    if (!hashed_passwords) {
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        // Generate a random salt
        if (RAND_bytes(hashed_passwords[i].salt, 32) != 1) {
            // Free memory and return on failure
            for (int j = 0; j < i; j++) {
                free(hashed_passwords[j].salt);
                free(hashed_passwords[j].hash);
            }
            free(hashed_passwords);
            return NULL;
        }

        // Use PKCS5_PBKDF2_HMAC to derive the key
        unsigned char derived_key[32];
        if (PKCS5_PBKDF2_HMAC(passwords[i], strlen(passwords[i]), hashed_passwords[i].salt, 32, 10000, EVP_sha256(), 32, derived_key) != 1) {
